import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"linux 内核构建系统","description":"","frontmatter":{},"headers":[],"relativePath":"kernel/linux/develop/kbuild.md","filePath":"kernel/linux/develop/kbuild.md"}`),a={name:`kernel/linux/develop/kbuild.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="linux-内核构建系统" tabindex="-1">linux 内核构建系统 <a class="header-anchor" href="#linux-内核构建系统" aria-label="Permalink to “linux 内核构建系统”">​</a></h1><p>linux 内核构建系统是基于 gcc 和 makefile，并在此基础上添加了适用于内核构建的特性</p><p>内核没有标准库</p><p>-nostdinc # 不使用系统头文件 -ffreestanding # 不假设标准库存在 -fno-builtin # 不使用编译器内置函数替换 内核自己实现了 memcpy、printf（printk）等，不依赖 glibc。</p><p>NULL 不是无效地址</p><p>-fno-delete-null-pointer-checks # 禁止编译器优化掉 NULL 检查 在用户态，NULL (0x0) 永远不可访问，编译器会优化掉对 NULL 的检查。但在内核空间，地址 0 是合法的（尤其在 x86-32 上），不能被优化掉。</p><p>禁用浮点</p><p>-mno-sse -mno-mmx -mno-sse2 -mno-avx -mno-80387 内核代码不能使用浮点运算。因为切换 FPU/SSE 上下文代价高昂，内核选择完全不使用。需要浮点时，必须手动保存/恢复 FPU 状态。</p><p>红区不可用</p><p>-mno-red-zone # 仅 x86-64 x86-64 ABI 规定函数栈帧下方有 128 字节的&quot;红区&quot;可供叶函数使用而不必调整栈指针。但内核的中断随时会打断执行，红区会被覆盖，所以必须禁用。</p><p>内核代码模型</p><p>-mcmodel=kernel # 仅 x86-64 x86-64 内核运行在高位地址（0xffffffff80000000 起），超过普通 -mcmodel=small 的 2GB 寻址范围，必须用 kernel 模型。</p><p>禁止严格别名优化</p><p>-fno-strict-aliasing 内核大量做类型转换（type-punning），比如把一块内存既当 struct boot_params 又当 char[] 来操作。严格别名优化会破坏这些代码。</p><ol start="3"><li>GCC 插件体系</li></ol><p>内核还有自己的 GCC 插件（scripts/gcc-plugins/）：</p><p>┌─────────────────────────┬────────────────────────────────┐ │ 插件 │ 作用 │ ├─────────────────────────┼────────────────────────────────┤ │ randomize_layout_plugin │ 随机化结构体字段布局，防御攻击 │ ├─────────────────────────┼────────────────────────────────┤ │ stackleak_plugin │ 系统调用返回时擦除内核栈 │ ├─────────────────────────┼────────────────────────────────┤ │ latent_entropy_plugin │ 为变量注入随机熵 │ └─────────────────────────┴────────────────────────────────┘</p><ol start="4"><li>编译器抽象层</li></ol><p>内核通过头文件抹平 GCC 和 Clang 的差异：</p><p>include/linux/compiler_types.h → 根据 <strong>clang</strong>/<strong>GNUC</strong> 分发 ├─ include/linux/compiler-gcc.h # GCC 特定定义 └─ include/linux/compiler-clang.h # Clang 特定定义 include/linux/compiler_attributes.h # 统一的 <strong>attribute</strong> 宏</p><p>常用宏映射： #define __always_inline inline <strong>attribute</strong>((always_inline)) #define __packed <strong>attribute</strong>((packed)) #define __noreturn <strong>attribute</strong>((noreturn)) #define __cold <strong>attribute</strong>((cold)) #define noinstr noinline notrace // 不能被追踪/内联</p><h2 id="内核启动命令行参数" tabindex="-1">内核启动命令行参数 <a class="header-anchor" href="#内核启动命令行参数" aria-label="Permalink to “内核启动命令行参数”">​</a></h2><p>编译产出 bzImage 之后，控制内核行为的第二个入口是启动命令行（kernel cmdline）——Boot Loader 传递的 <code>console=ttyS0 root=/dev/sda1</code> 这类参数。内核启动早期解析它们并据此配置自身。调试开发场景的常用参数按功能分组：</p><p><strong>控制台与输出</strong>（调试第一需要——没有输出就没有信息）：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>console=ttyS0,115200</code></td><td>串口控制台（QEMU <code>-nographic</code>、无头服务器的标配）</td></tr><tr><td><code>console=tty0 console=ttyS0</code></td><td>双控制台——VGA 和串口同时输出（最后的 console 是 stdin/stdout 主设备）</td></tr><tr><td><code>earlyprintk=serial,ttyS0,115200</code></td><td>最早的输出通道——在 printk 初始化前就可用（调试启动早期崩溃）</td></tr><tr><td><code>printk.devkmsg=on</code></td><td>允许用户态写入 /dev/kmsg（测试注入）</td></tr><tr><td><code>loglevel=8</code></td><td>提高控制台日志级别（8=debug 全开）</td></tr></tbody></table><p><strong>内存与地址布局</strong>（调试内存管理、KASLR 相关问题）：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>nokaslr</code></td><td>禁用内核地址随机化——KASLR 让调试符号和断点全部失效，内核调试必加</td></tr><tr><td><code>mem=4G</code></td><td>限制内核可见内存（复现小内存场景）</td></tr><tr><td><code>memmap=4G$0x100000000</code></td><td>在指定物理地址保留内存（设备 DMA 缓冲、大页预留）</td></tr><tr><td><code>crashkernel=256M</code></td><td>为 kdump 的 crash kernel 预留内存</td></tr><tr><td><code>hugepages=1024</code></td><td>启动时预留大页</td></tr></tbody></table><p><strong>调试基础设施</strong>：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>oops=panic</code></td><td>oops 升级为 panic（避免带伤继续运行）</td></tr><tr><td><code>panic=5</code></td><td>panic 后 5 秒重启（配合看门狗做自动恢复）</td></tr><tr><td><code>kgdboc=ttyS1,115200</code></td><td>KGDB over console（串口连接 GDB 调试内核）</td></tr><tr><td><code>debug</code></td><td>提升子系统 debug 日志级别</td></tr><tr><td><code>initcall_debug</code></td><td>打印每个 initcall 的执行时间（定位启动慢的驱动）</td></tr><tr><td><code>ignore_loglevel</code></td><td>输出所有日志（无视 loglevel 设置）</td></tr></tbody></table><p><strong>故障注入与测试</strong>：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>failslab=</code> / <code>fail_page_alloc=</code></td><td>故障注入框架（测试错误处理路径）</td></tr><tr><td><code>fault_inject=</code></td><td>通用故障注入配置</td></tr><tr><td><code>ftrace_dump_on_oops</code></td><td>oops 时自动 dump ftrace 缓冲（事后分析现场）</td></tr><tr><td><code>trace_event=</code></td><td>启动时启用指定 tracepoint（捕获启动期事件）</td></tr></tbody></table><p><strong>根文件系统与 init</strong>（引导问题排查）：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>root=/dev/sda1 rootwait</code></td><td>根设备（rootwait 等待设备就绪——USB/NVMe 枚举慢时必需）</td></tr><tr><td><code>rootflags=</code></td><td>根文件系统挂载选项</td></tr><tr><td><code>init=/bin/sh</code></td><td>跳过 init 系统（救援模式——忘记密码、init 损坏）</td></tr><tr><td><code>rdinit=</code> / <code>rd.break</code></td><td>initramfs 阶段打断（dracut 的救援入口）</td></tr><tr><td><code>systemd.unit=emergency.target</code></td><td>systemd 的紧急目标</td></tr></tbody></table><p>命令行的解析机制：早期解析（<code>setup_arch</code> 前）处理 <code>earlycon</code>/<code>earlyprintk</code> 这类&quot;越早越好&quot;的参数；主体解析由 <code>parse_args</code> 遍历——每个参数匹配注册的 <code>__setup()</code> 或 <code>early_param()</code> 宏处理函数（驱动通过模块参数机制 <code>module_param</code> 注册自己的参数）。未识别的参数传递给 init 进程（<code>/proc/cmdline</code> 可查看完整命令行）。调试场景的实用习惯：维护一份 QEMU 启动脚本固定 <code>nokaslr console=ttyS0</code> 等参数组合——避免每次调试重新摸索。</p>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};